/**
 * Dropzone plus a file list with upload states (`design/components/file-upload.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/file-upload.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  createComputed,
  createMemo,
  createSignal,
  mergeProps,
  on,
  onCleanup,
  onMount,
  type JSX,
} from 'solid-js'

import {
  Each,
  Icon,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  formatBytes,
  gateFiles,
  itemOf,
  scope,
  type Defaults,
  type FileRejection,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/file-upload.module.css'
import FileUploadRow from './FileUploadRow'

export type FileUploadStatus = 'uploading' | 'done' | 'error'

export interface FileUploadItem {
  id: string
  name: string
  size?: number
  status: FileUploadStatus
  progress?: number
  message?: string
}

export interface FileUploadProps {
  /**
   * The native syntax (`.pdf`, `image/*`, `application/pdf`), applied to drops too.
   */
  accept?: string
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  disabled?: boolean
  /**
   * Always controlled, because the list and what happens to it are the app's state.
   */
  files?: FileUploadItem[]
  hint?: string
  invalid?: boolean
  /**
   * The app's size ceiling, in bytes. A file over it never reaches `onFilesAdd`.
   */
  maxSize?: number
  /**
   * All control and announcement text, localized by the application.
   */
  messages?: {
    retry: string
    remove: (name: string) => string
    progress: (name: string) => string
    announcement: (file: FileUploadItem) => string
    formatSize: (bytes: number) => string
  }
  /**
   * When `false`, a drop of several files keeps the first that passes and refuses the rest.
   */
  multiple?: boolean
  /**
   * Set on the hidden picker, for a native form post.
   */
  name?: string
  /**
   * Only files that passed the gate (`accept`, `maxSize`, `multiple`), from the picker or a
   * drop.
   */
  onFilesAdd: (files: File[]) => void
  /**
   * The counterpart of `onFilesAdd`: every file the gate refused, and why. `file-upload.md`
   * requires a rejection to be "a *visible row*, never a silent drop", and rows only come from
   * `files`, which the app owns. So the component refuses the file and returns it with a reason,
   * and the app renders the refusal as an `error` row in its own words. **Required.** If it were
   * optional, the spec's main guarantee would be optional too. A field that sets `maxSize` and
   * passes no `onReject` would silently drop an oversized file, with no row, no message and no
   * event, and the user would see a chosen file fail to appear. The component cannot write the
   * row itself, because the text and the list belong to the app, and it must not hide the
   * refusal. So the handler is required.
   */
  onReject: (rejections: FileRejection[]) => void
  onRemove: (id: string) => void
  /**
   * When supplied, `error` rows offer a retry.
   */
  onRetry?: (id: string) => void
  title?: string
}

/** Dropzone plus a file list with upload states. */
export default function FileUpload(given: FileUploadProps): JSX.Element {
  const props = mergeProps(
    {
      files: (() => [])(),
      multiple: true,
      title: 'Drop files or click to browse',
      disabled: false,
      invalid: false,
      messages: (() => ({
        retry: 'Retry',
        remove: (name: string) => `Remove ${name}`,
        progress: (name: string) => `${name} upload progress`,
        announcement: (file: FileUploadItem) =>
          file.status === 'done'
            ? `${file.name} uploaded`
            : file.status === 'error'
              ? file.message === undefined
                ? `${file.name} failed`
                : `${file.name} failed: ${file.message}`
              : '',
        formatSize: formatBytes,
      }))(),
    } as Defaults<
      FileUploadProps,
      'files' | 'multiple' | 'title' | 'disabled' | 'invalid' | 'messages'
    >,
    claimSlot(given, 'group'),
  )
  return scope(() => {
    const dragover = createCell(false)
    const picker = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const zone = elementRef<HTMLElement>()
    const zoneState = createDerived(() => (dragover.value ? 'dragover' : 'idle'))
    const add = createDerived(
      () => (list: FileList | null | undefined) =>
        !props.disabled &&
        list != null &&
        list.length > 0 &&
        ((gate) => (
          gate.accepted.length > 0 && props.onFilesAdd?.(gate.accepted),
          gate.rejected.length > 0 && props.onReject?.(gate.rejected)
        ))(
          gateFiles(Array.from(list), {
            accept: props.accept,
            multiple: props.multiple,
            maxSize: props.maxSize,
          }),
        ),
    )
    const rowsOf = createMemo(() => props.files)
    const rowsKey = (file: FileUploadItem) => file.id
    const [rowsLeaving, setRowsLeaving] = createSignal<
      { key: string; item: ReturnType<typeof rowsOf>[number]; at: number }[]
    >([])
    createComputed(
      on(rowsOf, (now, before) => {
        if (before === undefined) return
        const kept = new Set(now.map(rowsKey))
        const leaving = rowsLeaving().filter((entry) => !kept.has(entry.key))
        before.forEach((item, at) => {
          const key = rowsKey(item)
          if (!kept.has(key) && !leaving.some((entry) => entry.key === key))
            leaving.push({ key, item, at })
        })
        setRowsLeaving(leaving)
      }),
    )
    const rows = createMemo(() => {
      const entries = rowsOf().map((item) => ({
        item,
        key: rowsKey(item),
        open: true,
        done: () => {},
      }))
      for (const entry of [...rowsLeaving()].sort((a, b) => a.at - b.at))
        entries.splice(Math.min(entry.at, entries.length), 0, {
          item: entry.item,
          key: entry.key,
          open: false,
          done: () => setRowsLeaving((list) => list.filter((other) => other.key !== entry.key)),
        })
      return entries
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'FileUpload',
        element: () => zone.value,
        state: () => ({
          files: props.files.map((file) => ({ ...file })),
          rows: props.files.map((file) => ({ id: file.id, label: file.name })),
          disabled: props.disabled,
          invalid: props.invalid,
        }),
        actions: {
          remove: { argument: 'id', run: (value) => props.onRemove?.(value) },
          retry: {
            argument: 'id',
            run: (value) =>
              (() => {
                if ((props.onRetry !== undefined) !== true)
                  throw new Error('The field offers no retry.')
                if (props.files.find((file) => file.id === value)?.status !== 'error')
                  throw new Error('Only a failed upload is retried.')
                props.onRetry?.(value)
              })(),
          },
        },
        withholds: () => root.value,
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <div
        class={styles.root}
        data-state={zoneState.value}
        data-disabled={props.disabled ? '' : undefined}
        data-invalid={props.invalid ? '' : undefined}
        data-member="file-upload"
        ref={root.attach}
      >
        {/* dropzone */}
        <button
          class={styles.zone}
          type="button"
          disabled={props.disabled}
          data-state={zoneState.value}
          data-disabled={props.disabled ? '' : undefined}
          data-invalid={props.invalid ? '' : undefined}
          aria-label={props['aria-label']}
          aria-labelledby={props['aria-labelledby']}
          aria-describedby={props['aria-describedby']}
          aria-required={props['aria-required']}
          aria-invalid={props.invalid ? true : undefined}
          onclick={() => picker.value?.click()}
          ondragover={($event: DragEvent) => (
            $event.preventDefault(),
            !props.disabled && (dragover.value = true)
          )}
          ondragleave={($event: DragEvent) =>
            !($event.currentTarget as HTMLElement).contains($event.relatedTarget as Node | null) &&
            (dragover.value = false)
          }
          ondrop={($event: DragEvent) => (
            $event.preventDefault(),
            (dragover.value = false),
            add.value($event.dataTransfer?.files)
          )}
          ref={zone.attach}
        >
          <Icon name="upload" size="lg" />
          {/* title */}
          <span class={styles.title}>{props.title}</span>
          {props.hint !== undefined ? <span class={styles.hint}>{props.hint}</span> : null}
        </button>
        {/* picker */}
        <input
          class={styles.picker}
          type="file"
          accept={props.accept}
          multiple={props.multiple}
          name={props.name}
          disabled={props.disabled}
          tabindex="-1"
          onchange={($event: Event) => (
            add.value(($event.target as HTMLInputElement).files),
            (($event.target as HTMLInputElement).value = '')
          )}
          ref={picker.attach}
        />
        {props.files.length > 0 ? (
          <ul class={styles.list}>
            <Each of={rows()} by={(row) => row.key} renew>
              {(row) => (
                <FileUploadRow
                  file={row.item}
                  open={row.open}
                  size={
                    row.item.size === undefined
                      ? undefined
                      : props.messages.formatSize(row.item.size)
                  }
                  retryable={(props.onRetry !== undefined) === true}
                  retryLabel={props.messages.retry}
                  removeLabel={props.messages.remove(row.item.name)}
                  progressLabel={props.messages.progress(row.item.name)}
                  onRetry={() => props.onRetry?.(row.item.id)}
                  onRemove={() => props.onRemove?.(row.item.id)}
                  onDone={() => row.done()}
                />
              )}
            </Each>
          </ul>
        ) : null}
        {/* reader */}
        <span class={styles.reader} aria-live="polite">
          <Each of={props.files} by={(file) => file.id} renew>
            {(file) => <span>{props.messages.announcement(itemOf(file))}</span>}
          </Each>
        </span>
      </div>
    )
  })
}

FileUpload.controlKind = 'group'
